import pandas as pd
import re

def parse_amount(s):
    if pd.isna(s) or not str(s).strip():
        return float('nan')
    s = str(s).strip()
    is_neg = False
    if "CR" in s:
        is_neg = True
    elif s.startswith('(') and s.endswith(')'):
        is_neg = True
    elif "-" in s:
        is_neg = True

    s = s.replace("C1", "").replace("C2", "")

    chars = []
    for c in s:
        if c.isdigit() or c in [',', '.']:
            chars.append(c)
    s = "".join(chars)

    if not s:
        return float('nan')

    last_dot = s.rfind('.')
    last_comma = s.rfind(',')
    dec_idx = -1

    if last_dot != -1 and last_comma != -1:
        if last_dot > last_comma:
            dec_idx = last_dot
        else:
            dec_idx = last_comma
    elif last_dot != -1:
        if len(s) - last_dot == 3:
            dec_idx = last_dot
    elif last_comma != -1:
        if len(s) - last_comma == 3:
            dec_idx = last_comma

    res = []
    for i, c in enumerate(s):
        if c.isdigit():
            res.append(c)
        elif i == dec_idx:
            res.append('.')

    if not res:
        return float('nan')

    try:
        val = float("".join(res))
    except:
        return float('nan')

    if is_neg:
        val = -val
    return val

df = pd.read_csv('/app/dataset/data.csv')
for x in df['amount_str'].dropna().head(30):
    print(f"Original: {x!r} -> Parsed: {parse_amount(x)}")

